tool_input.command:
Start-Sleep -Seconds 3
Write-Output "=== ports after kill ==="; foreach ($p in @(8080,9222)) { $c = (Get-NetTCPConnection -LocalPort $p -State Listen -ErrorAction SilentlyContinue | Measure-Object).Count; Write-Output "port $p listening=$c" }
Write-Output "=== leftover java (common-portal/gateway jars) ==="; Get-CimInstance Win32_Process -Filter "Name='java.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match 'common-portal-server|common-gateway' } | Select ProcessId,@{n='cmd';e={($_.CommandLine -split ' ')[-1]}}
